function parseCardInternalIds(value) {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Invalid schedule file: cardInternalIds must be a non-empty array');
    const cardInternalIds = value.map((cardInternalId, index) => requireString(cardInternalId, `cardInternalIds[${index}]`));
    if (new Set(cardInternalIds).size !== cardInternalIds.length) {
        throw new Error('Invalid schedule file: duplicate sequence cardInternalId');
    }

    return cardInternalIds;
}

function parseSequenceSchedule(schedule, base) {
    const cardInternalIds = parseCardInternalIds(schedule.cardInternalIds);
    const currentIndex = requireNonNegativeInteger(schedule.currentIndex, 'currentIndex');
    if (currentIndex >= cardInternalIds.length) {
        throw new Error('Invalid schedule file: currentIndex must identify a sequence card');
    }

    if (schedule.branchProgress !== undefined && schedule.worktreeBranch === undefined) throw new Error('Sequence branch progress requires a worktree assignment');

    return {
        ...(schedule.agentSelection === undefined ? {} : { agentSelection: parseSequenceAgentSelection(schedule.agentSelection) }),
        ...(schedule.worktreeBranch === undefined ? {} : { worktreeBranch: requireString(schedule.worktreeBranch, 'worktreeBranch') }),
        ...(schedule.branchProgress === undefined ? {} : { branchProgress: parseSequenceBranchProgress(schedule.branchProgress) }),
        actionCompleted: requireBoolean(schedule.actionCompleted, 'actionCompleted'),
        actionId: requireString(schedule.actionId, 'actionId'),
        cardInternalIds,
        ...parseOptionalConversationId(schedule),
        currentIndex,
        currentRunId: requireNullableString(schedule.currentRunId, 'currentRunId'),
        failure: requireNullableString(schedule.failure, 'failure'),
        readyState: requireString(schedule.readyState, 'readyState'),
        readyStateMet: requireBoolean(schedule.readyStateMet, 'readyStateMet'),
        ...base,
    };
}

export function parseSequenceAgentSelection(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Invalid sequence agent selection');
    if (typeof value.agent !== 'string' || !value.agent) throw new Error('Missing sequence execution agent');
    if (typeof value.model !== 'string' || !value.model) throw new Error('Missing sequence execution model');
    const thinkingLevel = validateThinkingLevel(value.thinkingLevel, 'sequence agent selection');
    const selection = { agent: value.agent, model: value.model, thinkingLevel };
    if (value.accountId !== undefined) selection.accountId = requireString(value.accountId, 'agentSelection.accountId');
    if (value.permissionMode !== undefined) selection.permissionMode = validatePermissionMode(value.permissionMode, 'sequence agent selection');
    if (value.speedMode !== undefined) selection.speedMode = validateSpeedMode(value.speedMode, 'sequence agent selection');
    return selection;
}

function parseSchedule(value) {
    const schedule = requireObject(value, 'schedule');
    const base = parseBaseSchedule(schedule);

    return base.kind === 'action'
        ? parseActionSchedule(schedule, base)
        : parseSequenceSchedule(schedule, base);
}

/** Parse and validate persisted schedule JSON. */
export function parseScheduleFile(value) {
    const file = requireObject(value, 'root');
    if (!Array.isArray(file.schedules)) throw new Error('Invalid schedule file: schedules must be an array');

    return { schedules: file.schedules.map(parseSchedule) };
}

/** Build persisted schedule JSON after validating every record. */
export function createScheduleFile(schedules) {
    return parseScheduleFile({ schedules });
}

